---@alias gcp.recaptchaenterprise_v1.GoogleCloudRecaptchaenterpriseV1FraudSignalsCardSignalsCardLabelsItemEnumList (gcp.recaptchaenterprise_v1.GoogleCloudRecaptchaenterpriseV1FraudSignalsCardSignalsCardLabelsItemEnum|string)[]

